const b = $json.body ?? $json;

return [{
  json: {
    ticket_id: String(b.ticket_id ?? ''),
    category: String(b.category ?? ''),
    priority: String(b.priority ?? 'Medium')
  }
}];

const request = $('Read Dispatch Input').first().json;

if (!request.ticket_id || !request.category) {
  return [{
    json: {
      success: false,
      error: 'ticket_id and category are required'
    }
  }];
}

if (request.priority === 'Critical') {
  return [{
    json: {
      success: false,
      ticket_id: request.ticket_id,
      requires_human_review: true,
      message: 'Critical incidents require manual approval'
    }
  }];
}

const technicians = $input.all().map(item => item.json);

const matches = technicians.filter(t => {
  const skills = String(t.Skills ?? '')
    .toLowerCase()
    .split(',')
    .map(s => s.trim());

  const available =
    String(t.Availability ?? '').toLowerCase() === 'available';

  const activeJobs = Number(t.Active_Jobs ?? 0);
  const maxJobs = Number(t.Max_Jobs ?? 1);

  return skills.includes(request.category.toLowerCase())
    && available
    && activeJobs < maxJobs;
});

matches.sort((a, b) =>
  Number(a.Active_Jobs ?? 0) - Number(b.Active_Jobs ?? 0)
);

if (matches.length === 0) {
  return [{
    json: {
      success: false,
      ticket_id: request.ticket_id,
      message: 'No available matching technician. Manual assignment required.'
    }
  }];
}

const t = matches[0];

return [{
  json: {
    success: true,
    ticket_id: request.ticket_id,
    technician_id: t.Technician_ID,
    technician_name: t.Technician_Name,
    technician_email: t.Email,
    dispatch_status: 'Awaiting Confirmation',
    assigned_date: new Date().toISOString(),
    message: 'Technician successfully matched. Awaiting admin confirmation.'
  }
}];
